head.script:
scwin.gVar = {
    "cTitle" : "",
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트(초기값 secret)이며 con_title 에서 선택한 값이 title 속성으로 적용됩니다\n[절차] 위 조건 선택 -> Target 재생성 -> getTitle / text 확인 클릭\n[확인] getTitle 버튼이 출력하는 title 값과, 테스트 샘플 영역·입력창의 화면 관찰로 판정합니다 / text 확인 버튼은 항상 빈 값을 출력하므로 판정에 쓰지 않습니다"', '', 'label1');

    // 조건 설정 (con_title 선택값은 공통 판이 scwin.gVar 에 담아준다)
    let properties = {
        title : scwin.gVar["cTitle"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList);
}
